import { gql, useQuery } from '@apollo/client';

type GetUserQuery = {
  user: {
    id: string;
    name: string;
    email: string;
    posts: Array<{
      id: string;
      title: string;
    }>;
  };
};

function UserProfile({ userId }: { userId: string }) {
  const { data, loading, error } = useQuery<GetUserQuery>(
    gql`
      query GetUser($id: ID!) {
        user(id: $id) {
          id
          name
          email
          posts { id title }
        }
      }
    `,
    { variables: { id: userId } }
  );

  if (loading) return <p>Loading...</p>;
  return <div>{data?.user.name}</div>;
}

const cache = new InMemoryCache({
  typePolicies: {
    Query: {
      fields: {
        cartTotal: {
          read(_, { readField }) {
            const items = readField('cartItems');
            return items.reduce(
              (total, item) => total + item.price * item.quantity,
              0
            );
          }
        }
      }
    }
  }
});

// Query local-only field
const GET_CART = gql`
