function useDynamicQuery(fields: string[]) {
  const query = gql`
    query GetUser($id: ID!) {
      user(id: $id) {
        ${fields.join('\n')}
      }
    }
  `;
  return useQuery(query, {
    variables: { id: userId }
  });
}

// Usage
function UserCard() {
  const { data } = useDynamicQuery(['id', 'name', 'email']);
  return <div>{data.user.name}</div>;
}

function PriceTicker({ productId }) {
  const { data, error } = useQuery(GET_PRICE, {
    variables: { productId },
    pollInterval: 5000, // refetch every 5 seconds
    notifyOnNetworkStatusChange: true
  });

  const [isPolling, setIsPolling] = useState(false);

  useEffect(() => {
    setIsPolling(true);
    return () => setIsPolling(false);
  }, []);

  return (
    <div>
      <p>Price: ${data?.price ?? 'Loading...'}</p>
      <p>Status: {isPolling ? 'Live' : 'Paused'}</p>
    </div>
  );
}
